import{_ as o,o as a,c as t,a2 as s}from"./chunks/framework.Cdp8-jB6.js";const g=JSON.parse('{"title":"ADR-090 — Flight-map grand hero: a whole-mission scientific diagram per capstone/milestone","description":"","frontmatter":{},"headers":[],"relativePath":"adr/ADR-090.md","filePath":"adr/ADR-090.md"}'),n={name:"adr/ADR-090.md"};function i(r,e,l,c,d,h){return a(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="adr-090-—-flight-map-grand-hero-a-whole-mission-scientific-diagram-per-capstone-milestone" tabindex="-1">ADR-090 — Flight-map grand hero: a whole-mission scientific diagram per capstone/milestone <a class="header-anchor" href="#adr-090-—-flight-map-grand-hero-a-whole-mission-scientific-diagram-per-capstone-milestone" aria-label="Permalink to &quot;ADR-090 — Flight-map grand hero: a whole-mission scientific diagram per capstone/milestone&quot;">​</a></h1><blockquote><p>Status · Accepted · 2026-08-31 · Operator-directed (Physics Lab v0.9) · builds on ADR-087 (systems layer) + ADR-088/089 (entry) · adds the whole-mission grand hero to the capstone/milestone goals and unblocks the per-goal flight-map subsystem</p></blockquote><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Each Lab goal is a ladder of per-formula cards, and each card renders one figure &quot;hero&quot; (<code>FigureRenderer</code> → the canvas heroes). That answers <em>&quot;how does this one step work?&quot;</em> but nothing answered <em>&quot;what is the whole flight, end to end?&quot;</em> — the question a capstone is really about. A learner finishing the Apollo round-trip saw six good step figures but never one picture tying launch, trans-lunar injection, descent, ascent, trans-earth injection and entry into a single mission.</p><p>The operator asked for a <strong>data-driven scientific diagram of the whole flight</strong> — explicitly <em>not</em> a stylised poster — in the reference language of the NASA Apollo flight-plan chart and Nik Schulz&#39;s &quot;Destination Moon&quot;: a trajectory annotated with every event, its real MET/Δv, and the spacecraft configuration at each phase; and to make it <strong>contextual with the rest of the Lab</strong> (blueprint teal, honesty line) and a <strong>showcase of how the flight works and why each phase matters</strong>.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Add a <strong>goal-level grand hero</strong> — one wide canvas per capstone/milestone goal, above the notebook&#39;s step cards — rendered by a new reusable component and fed by a data module:</p><ul><li><strong><code>src/lib/lab/FlightMapCanvas.svelte</code></strong> — renders a <code>FlightMap</code>: a schematic trajectory (cubic béziers) over the Lab&#39;s blueprint background, bodies (with optional orbit rings and a planetary <strong>limb</strong> mode for ascent profiles), numbered <strong>event stations</strong> with <code>MET · physics</code> annotations (gold for burns), and a <strong>filmstrip</strong> of per-phase spacecraft-configuration line-icons.</li><li><strong><code>src/lib/lab/flight-maps.ts</code></strong> — the <code>FlightMap</code> descriptors, one per goal. The physically <strong>computable</strong> speeds/Δv are derived here from the same kernel the lessons use (<code>visVivaKms</code>, <code>circularVelocityKms</code>, <code>escapeVelocityKms</code>), so the map never disagrees with the cards. Non-computable values (historical MET, mid-course/ascent burn Δv) come from the flight record and are labelled as such on each map&#39;s honesty line.</li><li><strong><code>Notebook.svelte</code></strong> shows <code>getFlightMap(goal.id)</code> at the top of a goal&#39;s notebook when one exists.</li></ul><p>Shipped maps: <code>apollo-round-trip</code>, <code>get-to-mars</code>, <code>leave-the-solar-system</code>, <code>plan-a-mission</code>, <code>reach-orbit</code> (limb/ascent-profile mode), <code>reach-the-moon</code>.</p><h3 id="honesty-boundaries-the-load-bearing-part" tabindex="-1">Honesty boundaries (the load-bearing part) <a class="header-anchor" href="#honesty-boundaries-the-load-bearing-part" aria-label="Permalink to &quot;Honesty boundaries (the load-bearing part)&quot;">​</a></h3><ul><li><strong>Geometry is schematic, and says so.</strong> Distances are compressed for legibility (a true-scale Earth–Moon or Sun–Neptune map is unreadable). Every map&#39;s honesty line states &quot;schematic … not to scale&quot; and names which numbers ARE computed.</li><li><strong>Numbers are honest.</strong> Computable speeds/Δv come from the kernel; record values are named as record values. No faked physics.</li><li><strong>Canvas copy is English</strong>, matching every existing Lab hero (<code>EntrySteeringCanvas</code> et al.) — the hardcoded-copy convention. Only the connection-panel link labels (DOM text) are i18n&#39;d ×14.</li></ul><h2 id="also-in-this-change-same-lab-polish-pass" tabindex="-1">Also in this change (same Lab-polish pass) <a class="header-anchor" href="#also-in-this-change-same-lab-polish-pass" aria-label="Permalink to &quot;Also in this change (same Lab-polish pass)&quot;">​</a></h2><ul><li><strong>Three per-step heroes</strong> that were blank or generic curves now have bespoke canvases + figure kinds (<code>spec.ts</code>): <code>launch-window</code> → synodic phase-angle dial; <code>gravity-assist</code> → velocity-triangle deflection; <code>assist-chain</code> → cumulative-Δv staircase.</li><li><strong>Fleet-asset links</strong> added to the spaceflight goals that lacked them (Saturn V / CSM / Apollo 13 on the Moon goals; Mars Odyssey / Atlas V on get-to-Mars; Viking 1 on land-on-Mars; Voyager 1/2 on leave-the-solar-system), translated ×14.</li></ul><h2 id="alternatives-considered" tabindex="-1">Alternatives considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to &quot;Alternatives considered&quot;">​</a></h2><ul><li><strong>A stylised poster</strong> (screen-print, big display type). Prototyped and <strong>rejected by the operator</strong> — wanted a scientific diagram, not marketing art. The poster palette also clashed with the Lab.</li><li><strong>A porkchop/axed plot for the whole mission.</strong> Rejected: a single mission spans 10 min to years and 10⁴ km to 10⁹ km; no single axis pair reads. The trajectory-with-annotations form is the standard for a reason.</li><li><strong>True-scale geometry.</strong> Rejected: illegible. Schematic + an explicit honesty line is the honest compromise.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>New goal-level surface; <code>Notebook</code> gains one optional block. No change to the card/figure contract.</li><li>Adding a map for a new goal is data-only (<code>flight-maps.ts</code>) unless it needs a new config icon or the limb mode. The filmstrip icon set is a small closed union (<code>IconKind</code>).</li><li>Follow-ups: maps for the remaining milestones if wanted; wiring the annotations to live per-notebook input changes (today they read the kernel at module load with the lesson&#39;s canonical inputs).</li></ul>',17)])])}const m=o(n,[["render",i]]);export{g as __pageData,m as default};
